/** Message type of each subscribing command's Channel. */
export interface ChannelMessages {
  transcript_subscribe: TranscriptMsg;
  levels_subscribe: LevelsMsg;
  cards_subscribe: CardMsg;
  ask_start: AskMsg;
  self_test_run: SelfTestMsg;
}

export type ChannelCommand = keyof ChannelMessages;

/** Payload of each event (Tauri events, broadcast to every window). */
export interface EventPayloads {
  /**
   * The capture state machine, whole, on every change.
   */
  "capture:state": CaptureState;
  /**
   * The record prompt's detection appeared, changed or went away.
   */
  "capture:detected": DetectionChanged;
  /**
   * Copilot status for every window (menu bar mirrors are native).
   */
  "copilot:status": CopilotStatus;
  /**
   * Full current set of degraded states.
   */
  "degraded:changed": DegradedSet;
  /**
   * Full current set of app banners.
   */
  "banners:changed": BannerSet;
  /**
   * A record changed for any reason; replace it by id.
   */
  "entity:changed": EntityChanged;
  /**
   * A post-call output section changed state.
   */
  "outputs:progress": OutputsProgress;
  /**
   * A job run started, progressed or finished.
   */
  "jobs:progress": JobProgress;
  /**
   * Sidebar counts for Activity.
   */
  "proposals:counts": ProposalCounts;
  "setup:changed": SetupStatus;
  /**
   * Displays, output route, permissions, notifications, online, update, disk.
   */
  "env:changed": EnvironmentState;
  "settings:changed": Settings;
  "privacy:changed": PrivacyStatus;
  "accounts:changed": AccountsView;
  "signin:progress": SignInProgress;
  "hotkeys:changed": HotkeyList;
  "playback:state": PlaybackState;
  "window:call": CallWindowState;
  "app:presenting": PresentingState;
  /**
   * The core asks the main or Settings window to navigate (notification click, menu).
   */
  "nav:request": NavTarget;
}

export type EventName = keyof EventPayloads;

